effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat6;
float u_xlat12;
float u_xlat18;
void main()
{
    u_xlat0.xy = acScreenNorm.xy * vec2(_scale);
    u_xlat12 = _cur_time * _speed;
    u_xlat0.x = _direction * u_xlat0.y + u_xlat0.x;
    u_xlat18 = _intensity * 0.25;
    u_xlat1.x = u_xlat0.x * 3.0 + 0.100000001;
    u_xlat2 = vec4(u_xlat12) * vec4(0.800000012, 0.00999999978, 1.20000005, 0.200000003);
    u_xlat1.y = u_xlat0.y * 3.0 + u_xlat2.x;
    u_xlat0.x = texture(texture0, u_xlat1.xy).x;
    u_xlat0.x = u_xlat18 * u_xlat0.x;
    u_xlat3.x = u_xlat1.x * 0.649999976 + 0.100000001;
    u_xlat3.y = u_xlat1.y * 0.649999976 + u_xlat12;
    u_xlat6.x = texture(texture0, u_xlat3.xy).x;
    u_xlat6.x = u_xlat18 * u_xlat6.x;
    u_xlat6.x = u_xlat6.x * 0.5;
    u_xlat0.x = u_xlat0.x * 0.300000012 + u_xlat6.x;
    u_xlat1.x = u_xlat3.x * 0.649999976 + 0.100000001;
    u_xlat1.y = u_xlat3.y * 0.649999976 + u_xlat2.z;
    u_xlat6.x = texture(texture0, u_xlat1.xy).x;
    u_xlat6.x = u_xlat18 * u_xlat6.x;
    u_xlat0.x = u_xlat6.x * 0.699999988 + u_xlat0.x;
    u_xlat3.x = u_xlat1.x * 0.5 + 0.100000001;
    u_xlat3.y = u_xlat1.y * 0.5 + u_xlat2.z;
    u_xlat6.x = texture(texture0, u_xlat3.xy).x;
    u_xlat6.x = u_xlat18 * u_xlat6.x;
    u_xlat0.x = u_xlat6.x * 0.899999976 + u_xlat0.x;
    u_xlat1.x = u_xlat3.x * 0.400000006 + 0.100000001;
    u_xlat1.y = u_xlat3.y * 0.400000006 + u_xlat2.z;
    u_xlat6.x = texture(texture0, u_xlat1.xy).x;
    u_xlat6.x = u_xlat18 * u_xlat6.x;
    u_xlat0.x = u_xlat6.x * 0.899999976 + u_xlat0.x;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat3.xy = u_xlat0.xx * vec2(vec2(_distortion, _distortion)) + acScreenNorm.xy;
    u_xlat3 = texture(inputImg, u_xlat3.xy);
    u_xlat3 = u_xlat0.xxxx + u_xlat3;
    u_xlat3 = (-u_xlat1) + u_xlat3;
    u_xlat3 = vec4(_blend) * u_xlat3 + u_xlat1;
    u_xlat2.x = acScreenNorm.x * 0.00100000005 + u_xlat2.w;
    u_xlat0.x = texture(texture0, u_xlat2.xy).y;
    u_xlat0.x = u_xlat18 * u_xlat0.x;
    u_xlat0.x = dot(u_xlat0.xx, vec2(vec2(_flash, _flash)));
    u_xlat2 = u_xlat0.xxxx + u_xlat3;
    u_xlat0.x = u_xlat12 * 32.0;
    u_xlat0.x = floor(u_xlat0.x);
    u_xlat6.x = u_xlat0.x * 0.0625;
    u_xlat6.x = acScreenNorm.x * 2.0 + u_xlat6.x;
    u_xlat0.x = u_xlat0.x * 0.055555556 + acScreenNorm.y;
    u_xlat18 = u_xlat12 * _direction;
    u_xlat3.x = (-u_xlat18) * 0.550000012 + u_xlat6.x;
    u_xlat3.y = u_xlat12 * 0.150000006 + u_xlat0.x;
    u_xlat0.x = texture(texture0, u_xlat3.xy).z;
    u_xlat3 = acScreenNorm.xyxy * _resolution.xyxy + vec4(3.0, 3.0, 3.0, -3.0);
    u_xlat3 = u_xlat3 / _resolution.xyxy;
    u_xlat4 = texture(inputImg, u_xlat3.xy);
    u_xlat3 = texture(inputImg, u_xlat3.zw);
    u_xlat3 = (-u_xlat3) + u_xlat4;
    u_xlat6.xy = acScreenNorm.xy * _resolution.xy + vec2(-3.0, 3.0);
    u_xlat6.xy = u_xlat6.xy / _resolution.xy;
    u_xlat5 = texture(inputImg, u_xlat6.xy);
    u_xlat4 = u_xlat4 + (-u_xlat5);
    u_xlat3 = abs(u_xlat3) + abs(u_xlat4);
    u_xlat3 = u_xlat3 * vec4(0.5, 0.5, 0.5, 0.5);
    u_xlat6.x = dot(u_xlat3, u_xlat3);
    u_xlat6.x = sqrt(u_xlat6.x);
    u_xlat0.x = u_xlat0.x * u_xlat6.x;
    u_xlat0 = vec4(vec4(_drops, _drops, _drops, _drops)) * u_xlat0.xxxx + u_xlat2;
    u_xlat0 = (-u_xlat1) + u_xlat0;
    u_xlat0 = vec4(_blend) * u_xlat0 + u_xlat1;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
